record.field:
website = env.ref('solar_installation.website_industry')
to_deactivate = [ 'website.header_search_box', 'website.header_visibility_standard', 'website.homepage', 'website.contactus', ] to_activate = [ 'website.footer_custom', 'website.header_call_to_action', 'website.header_text_element', 'website.header_visibility_disappears', 'website.template_header_default_align_center', ]
ctx = {'website_id': website.id}
for xml_id in to_deactivate: env.ref(xml_id).with_context(**ctx).write({'active': False}) for xml_id in to_activate: env.ref(xml_id).with_context(**ctx).write({'active': True})
menus = env['website.menu'] base_domain = [('website_id', '=', website.id)]
# Rename/reorder the default menu: Home menus.search(base_domain + [('url', '=', '/')], limit=1).write({'name': 'Home', 'sequence': 1}) # Disable the default Contact us, Appointment and Events menus menus.search(base_domain + [('url', 'in', ['/contactus', '/appointment', '/event'])]).write({'website_id': False}) # Add Product & Services menu parent_menu = menus.search(base_domain + [('parent_id', '=', False)], limit=1) menus.create({ 'name': 'Products & Services', 'url': '/products-and-services', 'parent_id': parent_menu.id, 'website_id': website.id, 'sequence': 2, }) # Reorder the Help menu created by the helpdesk team's website form env.ref('solar_installation.helpdesk_team_1').website_menu_id.write({'sequence': 3})
